type linear = {weights: [][]f32, bias: []f32}

type module_list = {layers: []char_attn}

type char_attn = {q_proj: linear, k_proj: linear, v_proj: linear, glyph_proj: linear, out_proj: linear, d_model: i64, n_heads: i64, head_dim: i64, scale: f32}

type unet = {conv_layers: [][][]f32, time_embed: [][]f32, cross_attn_layers: [][][]f32}

type glyph_encoder = {embed: [][]f32, transformer_layers: [][][]f32, config_hidden_size: i64}

type text_tokenizer = {vocab: [][]i32, max_length: i64}

type glyph_cond_diffusion = {unet: unet, glyph_encoder: glyph_encoder, char_attn_layers: module_list, text_tokenizer: text_tokenizer}

type ocr_model = {weights: [][]f32}

type ocr_trainer = {model: glyph_cond_diffusion, ocr_model: ocr_model, cer_weight: f32, optimizer_lr: f32}

type llm_model = {weights: [][][]f32, embed: [][]f32, layers: i64}

type layout_planner = {tokenizer: text_tokenizer, llm: llm_model, schema: []i32}

def linear_forward [n][m][k] (lin: linear) (x: [n][m]f32): [n][k]f32 =
  let weights_t = transpose lin.weights
  let result = map (\row -> map (\col -> f32.sum (map2 (*) row col)) weights_t) x
  in map2 (\r_row b_row -> map2 (+) r_row (replicate (length r_row) b_row)) result lin.bias

def matmul [n][m][p] (a: [n][m]f32) (b: [m][p]f32): [n][p]f32 =
  map (\a_row -> map (\b_col -> f32.sum (map2 (*) a_row b_col)) (transpose b)) a

def transpose_4d [b][h][t][d] (x: [b][h][t][d]f32): [b][h][d][t]f32 =
  map (\batch -> map (\head -> transpose head) batch) x

def transpose_dims_1_2 [b][t][h][d] (x: [b][t][h][d]f32): [b][h][t][d]f32 =
  map (\batch -> transpose batch) x

def softmax [n] (arr: [n]f32): [n]f32 =
  let max_val = f32.maximum arr
  let exps = map (\x -> f32.exp (x - max_val)) arr
  let sum_exps = f32.sum exps
  in map (/ sum_exps) exps

def char_aware_attention_forward [b][t][c] (attn: char_attn) (x: [b][t][c]f32) (glyph_features: [b][t][]f32) (text_mask: [b][t]i32): [b][t][c]f32 =
  let d_model = attn.d_model
  let n_heads = attn.n_heads
  let head_dim = attn.head_dim
  let scale = attn.scale
  let q_flat = flatten x
  let q_2d = unflatten (b * t) c q_flat
  let q_proj_out = linear_forward attn.q_proj q_2d
  let q_reshaped = unflatten b t (flatten q_proj_out)
  let q_split = map (\batch -> map (\tok -> unflatten n_heads head_dim tok) batch) q_reshaped
  let q = transpose_dims_1_2 q_split
  let k_proj_out = linear_forward attn.k_proj q_2d
  let k_reshaped = unflatten b t (flatten k_proj_out)
  let k_split = map (\batch -> map (\tok -> unflatten n_heads head_dim tok) batch) k_reshaped
  let k = transpose_dims_1_2 k_split
  let v_proj_out = linear_forward attn.v_proj q_2d
  let v_reshaped = unflatten b t (flatten v_proj_out)
  let v_split = map (\batch -> map (\tok -> unflatten n_heads head_dim tok) batch) v_reshaped
  let v = transpose_dims_1_2 v_split
  let glyph_flat = flatten glyph_features
  let glyph_dim = length (glyph_features[0,0])
  let glyph_2d = unflatten (b * t) glyph_dim glyph_flat
  let glyph_bias_out = linear_forward attn.glyph_proj glyph_2d
  let glyph_bias_reshaped = unflatten b t (flatten glyph_bias_out)
  let glyph_bias_split = map (\batch -> map (\tok -> unflatten n_heads head_dim tok) batch) glyph_bias_reshaped
  let glyph_bias = transpose_dims_1_2 glyph_bias_split
  let k_t = transpose_4d k
  let attn_scores_1 = map2 (\q_b k_t_b -> map2 (\q_h k_t_h -> matmul q_h k_t_h) q_b k_t_b) q k_t
  let attn_scores_scaled = map (\batch -> map (\head -> map (\row -> map (* scale) row) head) batch) attn_scores_1
  let glyph_bias_t = transpose_4d glyph_bias
  let glyph_scores = map2 (\q_b gb_t_b -> map2 (\q_h gb_t_h -> matmul q_h gb_t_h) q_b gb_t_b) q glyph_bias_t
  let glyph_scores_scaled = map (\batch -> map (\head -> map (\row -> map (* scale) row) head) batch) glyph_scores
  let attn_scores = map2 (\b1 b2 -> map2 (\h1 h2 -> map2 (\r1 r2 -> map2 (+) r1 r2) h1 h2) b1 b2) attn_scores_scaled glyph_scores_scaled
  let attn_mask_expanded = map (\batch -> map (\tok -> replicate n_heads (replicate t tok)) batch) text_mask
  let attn_scores_masked = map2 (\scores_b mask_b -> map2 (\scores_h mask_h -> map2 (\scores_t mask_t -> map2 (\s m -> if m == 0 then -1e9f32 else s) scores_t mask_t) scores_h mask_h) scores_b mask_b) attn_scores attn_mask_expanded
  let attn_weights = map (\batch -> map (\head -> map softmax head) batch) attn_scores_masked
  let output_attn = map2 (\w_b v_b -> map2 (\w_h v_h -> matmul w_h v_h) w_b v_b) attn_weights v
  let output_transposed = transpose_dims_1_2 output_attn
  let output_flattened = map (\batch -> map (\tok -> flatten tok) batch) output_transposed
  let output_flat_2d = unflatten (b * t) c (flatten (flatten output_flattened))
  let output_proj = linear_forward attn.out_proj output_flat_2d
  let output_final = unflatten b t (flatten output_proj)
  in output_final

def unet_add_noise [b][c][h][w] (clean: [b][c][h][w]f32) (noise: [b][c][h][w]f32) (timesteps: [b]i64): [b][c][h][w]f32 =
  let alpha = map (\t -> f32.sqrt (1.0f32 - f32.i64 t / 1000.0f32)) timesteps
  let sigma = map (\t -> f32.sqrt (f32.i64 t / 1000.0f32)) timesteps
  in map2 (\a s -> map2 (\a_c s_c -> map2 (\clean_ch noise_ch -> map2 (\clean_row noise_row -> map2 (\c_pix n_pix -> a * c_pix + s * n_pix) clean_row noise_row) clean_ch noise_ch) a_c s_c)) alpha sigma |> (\f -> map3 (\al si cl -> f al si cl) alpha sigma clean)

def unet_forward [b][c][h][w] (unet: unet) (noisy: [b][c][h][w]f32) (timestep: [b]i64) (encoder_hidden: [][]f32): [b][c][h][w]f32 =
  let time_embed = map (\t -> map (\layer -> f32.sin (f32.i64 t * layer)) (unet.time_embed[0])) timestep
  let conv_out = map (\batch -> map (\channel -> map (\row -> map (\pix -> pix + 0.01f32) row) channel) batch) noisy
  let cross_attn_flat = flatten (flatten encoder_hidden)
  let cross_result = map (\batch -> map (\ch -> map (\row -> map (\pix -> pix * 0.99f32) row) ch) batch) conv_out
  in cross_result

def glyph_encoder_forward [b][t] (enc: glyph_encoder) (input_ids: [b][t]i32): [b][t][]f32 =
  let vocab_size = length enc.embed
  let hidden_size = enc.config_hidden_size
  let embedded = map (\batch -> map (\tok -> if tok >= 0 && tok < i32.i64 vocab_size then enc.embed[i64.i32 tok] else replicate hidden_size 0.0f32) batch) input_ids
  let transformed = map (\batch -> map (\emb -> map (\v -> v + 0.01f32) emb) batch) embedded
  in transformed

def tokenizer_encode (tokenizer: text_tokenizer) (text: []i32): []i32 =
  let max_len = tokenizer.max_length
  let padded = if length text < max_len then concat text (replicate (max_len - length text) 0i32) else take max_len text
  in padded

def glyph_cond_diffusion_forward [b][c][h][w] (model: glyph_cond_diffusion) (noisy_image: [b][c][h][w]f32) (timestep: [b]i64) (text_prompt: []i32) (layout: [][][]f32): [b][c][h][w]f32 =
  let text_inputs = tokenizer_encode model.text_tokenizer text_prompt
  let text_inputs_batched = replicate b text_inputs
  let text_embeddings_raw = glyph_encoder_forward model.glyph_encoder text_inputs_batched
  let text_embeddings = map (\batch -> map flatten batch) text_embeddings_raw
  let num_text_boxes = length layout
  let glyph_embeddings_list = map (\text_box -> glyph_encoder_forward model.glyph_encoder (replicate b (map i32.i64 (iota 10)))) layout
  let glyph_embeddings_flat = map (\ge -> flatten (map flatten ge)) glyph_embeddings_list
  let glyph_embeddings = if num_text_boxes > 0 then replicate b (concat_to (length glyph_embeddings_flat) (map (\g -> if length g > 0 then g[0] else replicate 768 0.0f32) glyph_embeddings_flat)) else replicate b (replicate 768 0.0f32)
  let text_masks = replicate b (replicate (length text_inputs) 1i32)
  let noise_pred = unet_forward model.unet noisy_image timestep (flatten text_embeddings)
  let noise_flat_4d = noise_pred
  let noise_shape = (b, c, h * w)
  let noise_pred_flat = map (\batch -> flatten (map flatten batch)) noise_flat_4d
  let t_seq = h * w
  let noise_reshaped = map (\batch -> unflatten t_seq c batch) noise_pred_flat
  let attn_out = loop current = noise_reshaped for i < length model.char_attn_layers.layers do
    char_aware_attention_forward model.char_attn_layers.layers[i] current glyph_embeddings text_masks
  let noise_final_flat = map (\batch -> flatten batch) attn_out
  let noise_final = map (\batch -> unflatten c h (unflatten (c * h) w batch)) noise_final_flat
  in noise_final

def calculate_cer (ground_truth: []i32) (predicted: []i32): f32 =
  let m = length ground_truth
  let n = length predicted
  let dp0 = replicate (m + 1) (replicate (n + 1) 0i32)
  let dp1 = loop dp = dp0 for i < m + 1 do
    let row = dp[i] with [0] = i32.i64 i
    in dp with [i] = row
  let dp2 = loop dp = dp1 for j < n + 1 do
    let row0 = dp[0] with [j] = i32.i64 j
    in dp with [0] = row0
  let dp3 = loop dp = dp2 for i < m do
    let i1 = i + 1
    let row_i1 = loop row = dp[i1] for j < n do
      let j1 = j + 1
      let cost = if ground_truth[i] == predicted[j] then 0i32 else 1i32
      let deletion = dp[i][j1] + 1i32
      let insertion = row[j] + 1i32
      let substitution = dp[i][j] + cost
      let v = i32.min deletion (i32.min insertion substitution)
      in row with [j1] = v
    in dp with [i1] = row_i1
  let dist = f32.i32 dp3[m][n]
  let denom = i32.max 1i32 (i32.i64 m)
  in dist / f32.i32 denom

def ocr_recognize (ocr: ocr_model) (image: [][][]f32): []i32 =
  let flat = flatten (flatten image)
  let vocab_size = length ocr.weights
  let predictions = map (\w_row -> f32.sum (map2 (*) w_row (take (length w_row) flat))) ocr.weights
  let max_idx = reduce (\i j -> if predictions[i] > predictions[j] then i else j) 0i64 (iota vocab_size)
  in [i32.i64 max_idx]

def train_step [b][c][h][w] (trainer: ocr_trainer) (clean_image: [b][c][h][w]f32) (text_prompt: []i32) (layout: [][][]f32) (ground_truth_text: []i32): (f32, f32, f32) =
  let noise = map (\batch -> map (\ch -> map (\row -> map (\_ -> 0.01f32) row) ch) batch) clean_image
  let timesteps = map (\i -> i % 1000i64) (iota b)
  let noisy_image = unet_add_noise clean_image noise timesteps
  let predicted_noise = glyph_cond_diffusion_forward trainer.model noisy_image timesteps text_prompt layout
  let diff_squared = map2 (\pred_b noise_b -> map2 (\pred_c noise_c -> map2 (\pred_r noise_r -> map2 (\pred_p noise_p -> (pred_p - noise_p) ** 2.0f32) pred_r noise_r) pred_c noise_c) pred_b noise_b) predicted_noise noise
  let diffusion_loss = f32.sum (flatten (flatten (flatten diff_squared))) / f32.i64 (b * c * h * w)
  let denoised_image = predicted_noise
  let predicted_text = ocr_recognize trainer.ocr_model denoised_image[0]
  let cer = calculate_cer ground_truth_text predicted_text
  let cer_loss = cer
  let total_loss = diffusion_loss + trainer.cer_weight * cer_loss
  in (diffusion_loss, cer_loss, total_loss)

def llm_generate (llm: llm_model) (input_ids: []i32) (max_new_tokens: i64): []i32 =
  let vocab_size = length llm.embed
  let generated = loop current = input_ids for _ < max_new_tokens do
    let last_tok = current[length current - 1]
    let embed = if last_tok >= 0i32 && last_tok < i32.i64 vocab_size then llm.embed[i64.i32 last_tok] else replicate (length llm.embed[0]) 0.0f32
    let logits = map (\w_row -> f32.sum (map2 (*) w_row embed)) llm.weights[0,0]
    let max_idx = reduce (\i j -> if logits[i] > logits[j] then i else j) 0i64 (iota (length logits))
    in concat current [i32.i64 max_idx]
  in generated

def parse_json_layout (text: []i32): [][][]f32 =
  let num_boxes = 1i64
  let box_features = 7i64
  in replicate num_boxes (replicate 1 (replicate box_features 0.5f32))

def layout_planner_generate (planner: layout_planner) (prompt: []i32): [][][]f32 =
  let schema_prompt = concat planner.schema prompt
  let full_prompt = concat schema_prompt (replicate 10 32i32)
  let generated_ids = llm_generate planner.llm full_prompt 256i64
  let layout = parse_json_layout generated_ids
  in layout

def concat_to [n] (target_len: i64) (arr: [n]f32): []f32 =
  if n >= target_len then take target_len arr else concat arr (replicate (target_len - n) 0.0f32)

entry main (batch_size: i64) (channels: i64) (height: i64) (width: i64): f32 =
  let d_model = 512i64
  let n_heads = 8i64
  let head_dim = d_model / n_heads
  let glyph_dim = 768i64
  let q_weights = replicate d_model (replicate d_model 0.01f32)
  let q_bias = replicate d_model 0.0f32
  let q_proj = {weights = q_weights, bias = q_bias}
  let k_proj = {weights = q_weights, bias = q_bias}
  let v_proj = {weights = q_weights, bias = q_bias}
  let glyph_weights = replicate d_model (replicate glyph_dim 0.01f32)
  let glyph_bias = replicate d_model 0.0f32
  let glyph_proj = {weights = glyph_weights, bias = glyph_bias}
  let out_proj = {weights = q_weights, bias = q_bias}
  let scale = 1.0f32 / f32.sqrt (f32.i64 head_dim)
  let char_attn_layer = {q_proj = q_proj, k_proj = k_proj, v_proj = v_proj, glyph_proj = glyph_proj, out_proj = out_proj, d_model = d_model, n_heads = n_heads, head_dim = head_dim, scale = scale}
  let char_attn_layers = {layers = replicate 4 char_attn_layer}
  let unet_conv = replicate 3 (replicate 64 (replicate 64 0.01f32))
  let unet_time = replicate 1 (replicate 128 0.01f32)
  let unet_cross = replicate 1 (replicate 512 (replicate 768 0.01f32))
  let unet = {conv_layers = unet_conv, time_embed = unet_time, cross_attn_layers = unet_cross}
  let glyph_embed = replicate 30000 (replicate glyph_dim 0.01f32)
  let glyph_transformer = replicate 1 (replicate 12 (replicate glyph_dim 0.01f32))
  let glyph_encoder = {embed = glyph_embed, transformer_layers = glyph_transformer, config_hidden_size = glyph_dim}
  let tokenizer = {vocab = replicate 30000 (replicate 10 0i32), max_length = 77i64}
  let model = {unet = unet, glyph_encoder = glyph_encoder, char_attn_layers = char_attn_layers, text_tokenizer = tokenizer}
  let ocr_weights = replicate 256 (replicate 1000 0.01f32)
  let ocr = {weights = ocr_weights}
  let trainer = {model = model, ocr_model = ocr, cer_weight = 0.1f32, optimizer_lr = 0.0001f32}
  let llm_weights = replicate 1 (replicate 1 (replicate 50000 (replicate 768 0.01f32)))
  let llm_embed = replicate 50000 (replicate 768 0.01f32)
  let llm = {weights = llm_weights, embed = llm_embed, layers = 12i64}
  let schema = replicate 100 32i32
  let planner = {tokenizer = tokenizer, llm = llm, schema = schema}
  let clean_image = replicate batch_size (replicate channels (replicate height (replicate width 0.5f32)))
  let text_prompt = replicate 10 42i32
  let layout = parse_json_layout text_prompt
  let ground_truth = replicate 20 65i32
  let (diff_loss, cer_loss, total_loss) = train_step trainer clean_image text_prompt layout ground_truth
  let layout_gen = layout_planner_generate planner text_prompt
  let cer_test = calculate_cer ground_truth (replicate 25 66i32)
  in total_loss + f32.sum (flatten (flatten layout_gen)) + cer_test
